// Dialog method to capture runtime user inputs for customer details
public Object dialog()
{
    Dialog                      dialog = super();
    Map                         models = TFMExportSetup::getTables();
    MapEnumerator               modelEnum = models.getEnumerator();
    MapEnumerator               tableEnum;                   

    // Set a title for dialog
    dialog.caption( 'Export data');
    fields = new Map (Types::String, Types::Class);
    while (modelEnum.moveNext())
    {
        dlg = dialog.addGroup(modelEnum.currentKey());
        dlg.hideIfEmpty(false);
        tableEnum = modelEnum.currentValue().GetEnumerator();
        while (tableEnum.moveNext())
        {
            checkmarkField = dialog.addField(extendedTypeStr(NoYesId), tableEnum.currentValue() ? tableEnum.currentValue() : tableEnum.currentKey(), tableEnum.currentKey());
            checkmarkField.value(1);
            fields.insert(tableEnum.currentKey(),checkmarkField);
        }
    }

    return dialog;
}

public static Map getTables()
{
    Map modelsTables = new Map (Types::String, Types::Class);
    #ifnot.isAX6
    Map tablesInModel;

    Microsoft.Dynamics.AX.Metadata.MetaModel.ModelInfo  modelInfo = TFMVersion::modelForClass(className2Id(classStr(TFMDocumentHandler)));
    var environment = Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory::GetApplicationEnvironment();
    str packageDir = environment.get_Aos().get_PackageDirectory();

    var runtimeProviderConfiguration = New Microsoft.Dynamics.AX.Metadata.Storage.Runtime.RuntimeProviderConfiguration(packageDir);
    var metadataProviderFactory =  New Microsoft.Dynamics.AX.Metadata.Storage.MetadataProviderFactory();
    var provider = metadataProviderFactory.CreateRuntimeProvider(runtimeProviderConfiguration);
    Microsoft.Dynamics.AX.Metadata.MetaModel.AxTable axTable;
    var myTables = provider.Tables.ListObjectsForModel(modelInfo.Name);

    var le = myTables.GetEnumerator();
    tablesInModel = new Map(Types::String, Types::String);
    while (le.MoveNext())
    {
        axTable = provider.Tables.Read(le.Current);    
        //if (!strScan(axTable.Tags,'NoExport',1,strLen(axTable.Tags)))
        if (axTable.TableGroup == Microsoft.Dynamics.AX.Metadata.Core.MetaModel.TableGroup::Parameter)
        {
            tablesInModel.insert(axTable.Name,axTable.Label);
        }
    }
    modelsTables.insert("@TFM:MEL18",tablesInModel);
    MapEnumerator models = TFMVersion::extensionModels().getEnumerator();
    while (models.moveNext())
    {

        tablesInModel = new Map(Types::String, Types::String);
        myTables = provider.Tables.ListObjectsForModel(models.currentKey());

        le = myTables.GetEnumerator();
        while (le.MoveNext())
        {
            axTable = provider.Tables.Read(le.Current);
            if (axTable.TableGroup == Microsoft.Dynamics.AX.Metadata.Core.MetaModel.TableGroup::Parameter)
            {
                tablesInModel.insert(axTable.Name,axTable.Label);
            }
        }
        modelsTables.insert(models.currentValue(),tablesInModel);
    }
    #endif
    #if.isAX6
    #AOT

    TreeNode                tn  = TreeNode::findNode(#classesPAth + '\\' + classstr(TFMDocumentHandler));
    ListEnumerator          lEnum = new SysDictClass(classNum(TFMDocumentHandler)).extendedBy(true).getEnumerator();
    int                     basemodel = tn.AOTGetModel();
    Set                     modelIds = new Set(Types::Integer);

    Map getTablesInModel(int _modelId)
    {
        Map                     tablesInModel = new Map(Types::String, Types::String);
        SysModelElement         element;
        SysModelElementData     elementData;
        SysDictTable            dt;

        while select elementData where elementData.ModelId == _modelId
            join element where element.RootModelElement == elementData.ModelElement && element.ElementType == UtilElementType::Table
        {
            dt = new SysDictTable(tableName2id(element.Name));

            tablesInModel.insert(element.name,dt.label());
        }
        return tablesInModel;
    }
    modelsTables.insert("@TFM:MEL18",getTablesInModel(basemodel));

    modelIds.add(baseModel);
    while (lEnum.moveNext())
    {
        tn  = TreeNode::findNode(#classesPAth + '\\' + classid2NAme(lEnum.current()));
        if(!modelIds.in(tn.AOTGetModel()))
        {
            modelsTables.insert(SysModelStore::modelId2Name(tn.AOTGetModel()),getTablesInModel(tn.AOTGetModel()));
            modelIds.add(tn.AOTGetModel());
        }
    }
    #endif
    return modelsTables;
}

