public void run()
{
    MapEnumerator mEnum = fields.getEnumerator();
    str             output;

    while ( mEnum.moveNext())
    {
        checkmarkField = mEnum.currentValue();
        if (!checkmarkField.value())
        {
            continue;
        }
        //Info (mEnum.currentKey() +' '+  strFmt('%1',checkmarkField.value()));

        output += this.getTable(mEnum.currentKey());
    }
    this.sendFileToUser(output);
}

private void sendFileToUser(str _output)
{
    str fileName = 'TFMExport';
    str contentType = 'application/text';
    str fileExtension = '.tfe';//SRSPrintDestinationSettings::findFileNameType(SRSReportFileFormat::PDF, SRSImageFileFormat::BMP);
    #if.isAX6
    System.IO.StreamWriter sw;
    str filePath = WinAPI::getSaveFileName(0,['Tasklet Factory Export format','*'+fileExtension],'',"@SYS56237",fileExtension,fileName);
    InteropPermission perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();

    sw = new System.IO.StreamWriter(filePath);
    sw.Write(_output);
    sw.Flush();
    sw.Close();
    sw.Dispose();

    CodeAccessPermission::revertAssert();


    #endif
    #ifnot.IsAX6 //365
    System.IO.MemoryStream stream = new System.IO.MemoryStream();
    System.IO.StreamWriter writer = new System.IO.StreamWriter(stream,System.Text.Encoding::GetEncoding(1252));
    writer.Write(_output);
    writer.Flush();

    stream.Position = 0;
    FileUploadTemporaryStorageStrategy fileUploadStrategy = new FileUploadTemporaryStorageStrategy();
    FileUploadTemporaryStorageResult fileUploadResult = fileUploadStrategy.uploadFile(stream, fileName + fileExtension, contentType , fileExtension);
    Browser br = new Browser();
    br.navigate(fileUploadResult.getDownloadUrl(),false, false);
    #endif
}

private str getTable(TableName _tableNAme)
{
    str             output;
    str             tmpStr;
    int             endPos;
    str             addedFields;
    Map             refs;
    MapEnumerator   refsEnum;
    Common table = new SysDictTable(tableName2Id(_tableName)).makeRecord();
    while select table
    {
        addedFields = '';
        tmpStr = table.xml();
        endPos = strScan(tmpStr, '</Table:Record>',1, strLen(tmpStr));
        refs =  this.addClassReferenceKey(table);
        refs.insert('RecId',int642Str(table.RecId));
        refsEnum = refs.getEnumerator();
        while (refsEnum.moveNext())
        {
            addedFields += '<Table:Field name="'+refsEnum.currentKey()+'">'+refsEnum.currentValue()+'</Table:Field>' + "@TFM:lineBreak";
        }
        tmpStr = subStr(tmpStr,1,endPos-1) + addedFields + subStr(tmpStr,endPos, strLen(tmpStr));
        //tmpStr = subStr(tmpStr,1,endPos-1) + '<Table:Field name="RecId">'+int642Str(table.RecId)+'</Table:Field>' + subStr(tmpStr,endPos, strLen(tmpStr));

        output += tmpStr;
    }
    return output;
}

private Map addClassReferenceKey(Common _table)
{
    DictTable       dt          = new DictTable(_table.tableId);
    Map             classRefs   = new Map(Types::String, Types::String);
    dictField       df;
    int             fieldCount  = dt.fieldCnt();
    int             fieldNo     = 0;

    for (fieldNo = 0; fieldNo <= fieldCount; fieldNo++)
    {
        df = new DictField(_table.tableId,dt.fieldCnt2Id(fieldNo));
        if (df.typeId() && (new DictType(df.typeId()).extend() == extendedTypeNum(ClassId) || df.typeId() == extendedTypeNum(ClassId)))
        {
            classRefs.insert(df.name() + 'AOTName', classId2Name(_table.(dt.fieldCnt2Id(fieldNo))));
        }
    }

    return classRefs;
}

public static void main(Args _args)
{
    TFMExportSetup printDialog = new TFMExportSetup();

    if (_args)
    {
        printDialog.setBuffer(_args.record());
    }

    // Prompt the dialog, if user clicks in OK it returns true
    if (printDialog.prompt())
    {
        printDialog.runOperation();
    }
}

